const fetchData=async()=>{try{const t=await fetch("https://raw.githubusercontent.com/dicodingacademy/a565-webtools-labs/099-shared-files/proyek-awal/DATA.json");if(!t.ok)throw new Error(`HTTP error! status: ${t.status}`);return(await t.json()).listStory}catch(t){return console.error("Error fetching data:",t),null}};module.exports=fetchData;